source_edits.find:
{
  name: "list_issues",
  description: "Lists issues, optionally filtered by status and assignee. Use to browse issues by those attributes; use search_issues to find issues by text in the title or body. Returns at most `limit` issues (default 50). Comments are included by default.",
  params: {
    status: z.string().optional().describe("Filter by issue status. One of: open, in_progress, blocked, closed. Any other value returns an error. Omit to include all statuses."),
    assignee: z.string().optional(),
    include_comments: z.boolean().optional(),
    limit: z.number().optional(),
  },
}

